{{
(() => {
  const status = appsmith.store.inboundStatusRow?.Status || appsmith.store.inboundStatusRow?.status || "";

  if (status === "DRAFT") {
    return [
      { label: "In Transit", value: "IN_TRANSIT" },
      { label: "Cancelled", value: "CANCELLED" }
    ];
  }

  if (status === "IN_TRANSIT") {
    return [
      { label: "Arrived", value: "ARRIVED" },
      { label: "Cancelled", value: "CANCELLED" }
    ];
  }

  if (status === "ARRIVED") {
    return [
      { label: "Receiving", value: "RECEIVING" },
      { label: "Cancelled", value: "CANCELLED" }
    ];
  }

  if (status === "RECEIVING") {
    return [
      { label: "Arrived", value: "ARRIVED" },
      { label: "Cancelled", value: "CANCELLED" }
    ];
  }

  return [
    { label: "No status change available", value: "" }
  ];
})()
}}
